// Checked only for surfaces that explicitly opt into this contract: like
// submitRecording, but a recording that would not run throws instead of
// being dropped. A valid empty Recording is accepted; Recorder::snap()
// returns nullptr on failure.
void submitRecordingChecked(
    skgpu::graphite::Recorder *recorder,
    skgpu::graphite::SyncToCpu syncToCpu = skgpu::graphite::SyncToCpu::kNo) {
  if (recorder == nullptr) {
    throw std::runtime_error(
        "Checked GPU submissions require a Graphite recorder");
  }
  auto recording = recorder->snap();
  if (recording == nullptr) {
    throw std::runtime_error("Cannot create checked Graphite recording");
  }
  std::lock_guard<std::mutex> lock(_mutex);
  auto *current = _current.load(std::memory_order_acquire);
  if (generationOf(recorder) != current->id ||
      current->lost.load(std::memory_order_acquire)) {
    throw std::runtime_error(
        "The GPU device was lost; a checked recording cannot run");
  }
  skgpu::graphite::InsertRecordingInfo info;
  info.fRecording = recording.get();
  auto status = current->context->insertRecording(info);
  if (!static_cast<bool>(status)) {
    throw std::runtime_error("Graphite rejected a checked recording: " +
                             status.message());
  }
  if (!current->context->submit(syncToCpu)) {
    throw std::runtime_error("Graphite checked submission failed");
  }
}

// Opt-in for consumers that release native buffers after GPU completion.
// Other Skia surfaces preserve their existing flush/snapshot behavior.
void enableCheckedSubmissions() {
  if (!getObject()->recorder()) {
    throw std::runtime_error(
        "Checked GPU submissions require a Graphite surface");
  }
  _checkedSubmissions = true;
}

void submitRecording(skgpu::graphite::Recorder *recorder,
                     skgpu::graphite::SyncToCpu syncToCpu =
                         skgpu::graphite::SyncToCpu::kNo) {
  if (_checkedSubmissions) {
    DawnContext::getInstance().submitRecordingChecked(recorder, syncToCpu);
  } else {
    DawnContext::getInstance().submitRecording(recorder, syncToCpu);
  }
}

